def _numeric_slots_clean(value: Any, slots: Tuple[str, ...]) -> bool:
    """数值子类的相关槽都还是**祖先**的实现 ⇒ 可用 C 槽读真值（否则不可证）。"""
    cls = type(value)
    for base in _NUMERIC_ANCESTORS:
        if isinstance(value, base):
            ancestor = base
            break
    else:
        return False
    if cls is ancestor:
        return True
